def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform rows/columns of the dominant background are ordinary empty
    # space, not dividers. A non-background uniform row separates panels.
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    dividers = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    panels = []
    start = 0
    for r in dividers + [h]:
        if start < r:
            panels.append((start, r))
        start = r + 1
    if len(panels) < 2:
        return [row[:] for row in grid]

    patterns = []
    for r0, r1 in panels:
        marks = {(r-r0, c): grid[r][c]
                 for r in range(r0, r1) for c in range(w)
                 if grid[r][c] != background}
        patterns.append((r0, r1, marks))
    source = max(patterns, key=lambda item: len(item[2]))
    sh, motif = source[1] - source[0], source[2]
    out = [row[:] for row in grid]
    for r0, r1, _ in patterns:
        if r1 - r0 != sh:
            continue
        for (dr, c), value in motif.items():
            out[r0 + dr][c] = value
    return out
